import axios from 'axios'
import { React, useEffect, useState } from 'react'
import { Link } from "react-router-dom"

useEffect(() => {
    const fetchAllMembers = async () => {
        try {
            const res = await axios.get("http://localhost:8800")
            setMembers(res.data)
        } catch(err) {
            console.log(err)
        }
    }
    fetchAllMembers()
}, [])

const membershipStat = async (membership) => {
    if (membership) {
        return "Yes"
    }
    return "No"
}

const handleDelete = async (id) => {
    try {
        await axios.delete("http://localhost:8800" + id)
        window.location.reload()
    } catch (err) {
        console.log(err)
    }
}

const Members = () => {
    const [members, setMembers] = useState([])

    return ( 
        <div>
            <h1>Members List</h1>

            <div className="members">
                {members.map((member) => (
                    <div className="member" key={member.id}>
                        {member.cover && <img src="" alt="" />}
                        <h2>Member name: {member.name}</h2>
                        <h2>Membership: {membershipStatus(member.membership)}</h2>
                        <h2>Age: {member.age}</h2>
                        <button className="delete" onClick={() => handleDelete(member.id)}>Delete</button>
                    </div>
                ))}
            </div>
            <button>
                <Link to="/add">Add new member</Link>
            </button>
        </div>
    )
}

export default Members
